// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address ref) public {
        vm.assume(caller != address(0));
        vm.assume(ref != address(0));
        vm.assume(block.timestamp > 0);

        // Seed the market to initialize
        c.seedMarket{value: 1 ether}(100);

        // Give the caller some starting kilos
        vm.prank(caller);
        c.getFreeKilo();

        // Record lastCollect before the call
        uint256 lastCollectBefore = c.lastCollect(caller);

        // Call collectDrugs
        vm.prank(caller);
        c.collectDrugs(ref);

        // Assert that lastCollect for the caller is not 0 AFTER the call
        uint256 lastCollectAfter = c.lastCollect(caller);
        assertTrue(lastCollectAfter != 0);
    }
}

